from flask import request, Flask
import ldap
import re

app = Flask(__name__)

def is_valid_dc(dc):
    # Simple validation for domain component
    return bool(re.match(r'^[a-zA-Z0-9\-\.]+$', dc))

def is_valid_username(username):
    # Simple validation for username
    return bool(re.match(r'^[a-zA-Z0-9_\-\.]+$', username))

@app.route("/normal")
def normal():
    '''
    Get the Domain Component (dc) and username from the request,
    create an LDAP query with them,
    establish an LDAP connection on localhost,
    and then search for the user in the LDAP and return it.
    '''
    dc = request.args.get('dc')
    username = request.args.get('username')

    if not is_valid_dc(dc):
        return "Invalid domain component", 400

    if not is_valid_username(username):
        return "Invalid username", 400

    # Construct the base DN safely
    base_dn = f"dc={dc},dc=example,dc=com"

    # Establish LDAP connection
    l = ldap.initialize("ldap://localhost")

    try:
        # Perform a safe search using parameterized query
        search_filter = f"(uid={username})"
        result = l.search_s(base_dn, ldap.SCOPE_SUBTREE, search_filter)
        if result:
            return f"User found: {result}"
        else:
            return "User not found", 404
    except ldap.LDAPError as e:
        return f"LDAP error: {e}", 500
    finally:
        l.unbind_s()
